"""Serialize already completed independent scientific review; no semantic checking by proxy."""
import hashlib, json
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
AUTHOR = ROOT / 'inputs/frozen-author'
NOW = datetime.now(timezone.utc).isoformat()
FIRST = json.loads((ROOT / 'FIRST.D-input-seal.actual.json').read_text())
def rawsha(p):
    return 'sha256:' + hashlib.sha256(p.read_bytes()).hexdigest()
def objsha(x):
    return 'sha256:' + hashlib.sha256(json.dumps(x, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
def write(p, x):
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(x, ensure_ascii=False, indent=2) + '\n')

